package com.shopsphere.controller; import com.shopsphere.dto.AuthDtos.CouponRequest; import com.shopsphere.entity.Coupon; import com.shopsphere.repository.CouponRepository; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/coupons") public class CouponController {private final CouponRepository repo;public CouponController(CouponRepository r){repo=r;} @PostMapping @PreAuthorize("hasRole('ADMIN')") public Coupon create(@Valid @RequestBody CouponRequest r){Coupon c=new Coupon();c.setCode(r.code().toUpperCase());c.setDiscountPercent(r.discountPercent());c.setExpiresAt(r.expiresAt());repo.save(c);return c;}}